SELECT 
FROM fund_plan_execution
WHERE execution_status = 'COMPLETED' AND org_id = #{orgId} AND is_deleted = 0

    AND actual_date >= #{startDate}


    AND actual_date <= #{endDate}

ORDER BY actual_date DESC

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN execution_status = 'COMPLETED' THEN 1 END) as completedCount, COUNT(CASE WHEN execution_status = 'IN_PROGRESS' THEN 1 END) as inProgressCount, COUNT(CASE WHEN delay_days > 0 THEN 1 END) as delayedCount, COALESCE(SUM(planned_amount), 0) as totalPlannedAmount, COALESCE(SUM(executed_amount), 0) as totalExecutedAmount, COALESCE(AVG(execution_rate), 0) as avgExecutionRate, COALESCE(AVG(execution_efficiency), 0) as avgExecutionEfficiency, COALESCE(AVG(delay_days), 0) as avgDelayDays FROM fund_plan_execution WHERE is_deleted = 0
AND org_id = #{orgId}
AND plan_id = #{planId}
AND execution_type = #{executionType}
AND execution_status = #{executionStatus}

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as executionCount, COUNT(CASE WHEN execution_status = 'COMPLETED' THEN 1 END) as completedCount, COALESCE(SUM(planned_amount), 0) as totalPlannedAmount, COALESCE(SUM(executed_amount), 0) as totalExecutedAmount, COALESCE(AVG(execution_rate), 0) as avgExecutionRate, COALESCE(AVG(execution_efficiency), 0) as avgEfficiency FROM fund_plan_execution WHERE org_id = #{orgId} AND is_deleted = 0
AND execution_type = #{executionType}
AND create_time >= DATE_SUB(CURDATE(), INTERVAL #{months} MONTH) GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC

